INSERT OR IGNORE INTO studio_activity_log (id,actor_user_id,actor_email,actor_name,action,entity_type,entity_id,entity_label,details,created_at) VALUES ('ea76151b-4e4e-4fc6-941f-3296e4425fc7','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com',NULL,'insert','studio_world_records','fa7dca29-383c-4452-8757-cf2bc3678f30','Bone Dragon / Hybrid Elemental Dragon
Parentage: Terrax + Leviathans
Important family relationships: Son of Terrax and Leviathans; protective older brother of Ife; related to Rahim, Gaius and Shailara through shared parents.
Primary element/power: Bone — synthesis of Earth and Water.
Signature appearance: Long black hair, warm brown complexion, amber-gold eyes, ivory living bone armor and Indian-inspired clothing.','{"workflow_status":"draft"}','2026-09-25T01:19:48.694582+00:00');
INSERT OR IGNORE INTO studio_activity_log (id,actor_user_id,actor_email,actor_name,action,entity_type,entity_id,entity_label,details,created_at) VALUES ('34cb46da-cc98-47b0-8265-06e089089908','db618e68-0656-4b9b-b308-81e071faf745','Bryannaparker2521@gmail.com',NULL,'insert','studio_world_records','3d095ec9-656f-4065-acb9-e1b3fecf35bc','Family is something one actively maintains.
Love: Love is demonstrated through action.
Death: Even the strongest structure eventually returns to the world.
Magic: Magic should be understood before it is wielded recklessly.
Religion/spirituality: TBD.
Authority: Respect should be earned.
Strength: True strength is the ability to endure without abandoning responsibility.
Weakness: Weakness is not failure; refusing to acknowledge damage is dangerous.
Good and evil: Actions matter more than titles.','{"workflow_status":"draft"}','2026-09-25T01:19:48.787467+00:00');
